// helper: reset level sampled at the previous rising edge
logic rst_n_q = 1'b0;
always_ff @(posedge i_clk_core) rst_n_q <= i_rst_n_core;

// CHK-012: D_READY is 0 in reset and 1 from the first edge after release (BR-3-21, BR-3-22, BR-5.3-04, BR-6.2-15, BR-15.3-06, BR-20-11)
a_CHK_012: assert property (@(posedge i_clk_core) ((!i_rst_n_core) || rst_n_q) |-> (o_tlul_d_ready == i_rst_n_core))
  else begin fails_CHK_012++; $display("NNC_FAIL CHK-012 @%0t", $time); end
always_ff @(posedge i_clk_core) if ((!i_rst_n_core) || rst_n_q) hits_CHK_012 <= hits_CHK_012 + 1;

// CHK-013: Output values in reset and at the first edge after release (BR-3-31, BR-6.2-03, BR-6.2-04, BR-6.2-06, BR-6.2-15, BR-7.3-02, BR-7.3-03)
a_CHK_013: assert property (@(posedge i_clk_core) ((!i_rst_n_core) || (!rst_n_q)) |->
    (o_tlul_a_valid == 1'b0 && o_tlul_d_ready == 1'b0 && o_apb_pready == 1'b0 && o_apb_pslverr == 1'b0 &&
     o_apb_prdata == 32'h0 && o_tlul_a_opcode == 3'b000 && o_tlul_a_address == '0 && o_tlul_a_data == 32'h0))
  else begin fails_CHK_013++; $display("NNC_FAIL CHK-013 @%0t", $time); end
always_ff @(posedge i_clk_core) if ((!i_rst_n_core) || (!rst_n_q)) hits_CHK_013 <= hits_CHK_013 + 1;
